import data from "@/data/keep-downloads.json";

// The Phrozen Keep download library. Generated by scripts/keep-import/publish-downloads.ts; don't edit by hand.

export type DownloadStatus = "recovered" | "missing" | "dead-host";

export interface Download {
  id: number;
  title: string;
  /** The Keep's category path, e.g. ["Mod Archive - Lord of Destruction", "LoD v1.10"]. */
  category: string[];
  version?: string;
  filename?: string;
  description?: string;
  uploaded?: string;
  changed?: string;
  /** Download count on the Phrozen Keep. */
  keepDownloads?: number;
  originalUrl: string;
  status: DownloadStatus;
  /** Where the recovered file came from: the Keep's hosting backup or its Azure file mirror. */
  source?: "keep" | "azure";
  /** A public copy that still works, when there is one. */
  url?: string;
  bytes?: number;
  sha256?: string;
  deadLink?: string;
}

export interface DownloadCategory {
  slug: string;
  /** Short name within its section, e.g. "Lord of Destruction 1.10". */
  title: string;
  /** The Keep's parent category, when the title alone is ambiguous, e.g. "Audio Plugins". */
  parent?: string;
  /** The Keep's full path, e.g. "Mod Archive - Lord of Destruction / LoD v1.10". */
  path: string;
  section: DownloadSection;
  count: number;
}

export type DownloadSection = "mods" | "tools" | "plugins" | "game-files" | "resources";

export const DOWNLOAD_SECTIONS: Record<DownloadSection, { label: string; lead: string }> = {
  mods: { label: "Mods", lead: "Complete mods for Classic and Lord of Destruction, by the patch they were built for." },
  tools: { label: "Tools", lead: "Editors, extractors, mod managers and source code." },
  plugins: { label: "Plugins", lead: "Sounds, music, graphics, maps and DLL code to build into your own mod." },
  "game-files": { label: "Patches and clean installs", lead: "Official patch installers and clean copies of the game's files." },
  resources: { label: "Resources and history", lead: "Hosted sites, forum dumps and everything else the Keep kept." },
};

export const downloads = (data as Download[]).sort((a, b) => a.title.localeCompare(b.title, "en", { sensitivity: "base" }));

function sectionOf(top: string): DownloadSection {
  if (top.startsWith("Mod Archive") || top === "Darque Onyx Mods") return "mods";
  if (top === "Tools") return "tools";
  if (top.endsWith("Plugins")) return "plugins";
  if (top === "Patch Installers" || top === "Clean Install Files") return "game-files";
  return "resources";
}

const slugify = (s: string) =>
  s.toLowerCase().replace(/&/g, " and ").replace(/['’]/g, "").replace(/[^a-z0-9.]+/g, "-").replace(/\./g, "").replace(/^-+|-+$/g, "");

const shortTitle = (path: string[]) =>
  path[path.length - 1].replace(/^LoD v/, "Lord of Destruction ").replace(/^CD2 v/, "Classic ").replace(/^Tools - /, "");

export const downloadCategories: DownloadCategory[] = (() => {
  const byPath = new Map<string, DownloadCategory>();
  for (const d of downloads) {
    const key = d.category.join(" / ");
    const c = byPath.get(key) ?? {
      slug: slugify(key.replace(/^Mod Archive - /, "")),
      title: shortTitle(d.category),
      parent: d.category.length > 1 && !d.category[0].startsWith("Mod Archive") && d.category[0] !== "Tools" ? d.category[0] : undefined,
      path: key,
      section: sectionOf(d.category[0]),
      count: 0,
    };
    c.count++;
    byPath.set(key, c);
  }
  return [...byPath.values()].sort((a, b) => a.path.localeCompare(b.path, "en", { numeric: true }));
})();

export const categoryOf = (d: Download) => downloadCategories.find((c) => c.path === d.category.join(" / "))!;
export const getDownload = (id: number) => downloads.find((d) => d.id === id);
export const getDownloadCategory = (slug: string) => downloadCategories.find((c) => c.slug === slug);
export const downloadsIn = (slug: string) => downloads.filter((d) => categoryOf(d).slug === slug);

/** The version, unless the title already says it ("Battle for Elements v1.20"). */
export const extraVersion = (d: { title: string; version?: string }) =>
  d.version && !d.title.toLowerCase().includes(d.version.toLowerCase().replace(/^v\.?\s*/, "")) ? d.version : undefined;

export function formatBytes(n?: number) {
  if (n === undefined) return undefined;
  if (n < 1024) return `${n} B`;
  const units = ["KB", "MB", "GB"];
  let v = n / 1024;
  let i = 0;
  while (v >= 1024 && i < units.length - 1) {
    v /= 1024;
    i++;
  }
  return `${v < 10 ? v.toFixed(1) : Math.round(v)} ${units[i]}`;
}

export const DOWNLOAD_STATUS: Record<DownloadStatus, string> = {
  recovered: "Recovered",
  missing: "Missing",
  "dead-host": "Lost with its host",
};

export function downloadStats() {
  const recovered = downloads.filter((d) => d.status === "recovered");
  return {
    total: downloads.length,
    recovered: recovered.length,
    bytes: recovered.reduce((t, d) => t + (d.bytes ?? 0), 0),
    keepDownloads: downloads.reduce((t, d) => t + (d.keepDownloads ?? 0), 0),
    oldest: downloads.map((d) => d.uploaded).filter(Boolean).sort()[0],
  };
}
